/**
 * Noto Sans Sinhala (Sinhala + Latin subsets, merged), as base64.
 *
 * The PDF library can only draw letters that are inside the PDF itself, and
 * its built-in fonts have no Sinhala. Without this file every Sinhala
 * description had to be thrown away at export time. It lives in its own
 * module so that it is only fetched when someone actually exports a PDF,
 * and never weighs on the app opening.
 *
 * Licence: SIL Open Font License 1.1 (Google Noto).
 * Source: @fontsource/noto-sans-sinhala, latin + sinhala subsets merged,
 * with layout tables removed as the PDF library does not read them.
 */
export const SINHALA_FONT_BASE64 =
  "";
